-- BIGSERIAL no avanza solo con ids explícitos: la próxima orden debe ser la 33.
SELECT setval(pg_get_serial_sequence('work_orders', 'id'), (SELECT MAX(id) FROM work_orders));

-- Se prefiere un arranque roto a un seed a medias: si un subselect de usuario dio NULL,
-- una orden en progreso o cerrada quedaría sin dueño o sin autor de cierre.
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM work_orders WHERE status <> 'pending' AND taken_by_id IS NULL) THEN
        RAISE EXCEPTION 'Seed de órdenes incompleto: hay una orden no pending sin dueño';
    END IF;
    IF EXISTS (SELECT 1 FROM work_orders WHERE status IN ('completed', 'cancelled') AND closing_author_id IS NULL) THEN
        RAISE EXCEPTION 'Seed de órdenes incompleto: hay una orden cerrada sin autor de cierre';
    END IF;
END $$;
